// ═══════════════════════════════════════════════════════════════
// Build Arabic RTL HTML Dashboard from database query results
// لوحة معلومات الرصد الجنائي
// ═══════════════════════════════════════════════════════════════

const statsRow = $('Get Statistics').first().json || {};
const typeSummary = $('Get Report Type Summary').all().map(i => i.json).filter(r => r && r.report_type);
const recentReports = $('Get Recent Reports').all().map(i => i.json).filter(r => r && r.id);
const recentRefs = $('Get Recent References').all().map(i => i.json).filter(r => r && r.id);
const timeline = $('Get Monthly Timeline').all().map(i => i.json).filter(r => r && r.month);

// ─── Arabic label maps for database enums ───
const crimeTypeAr = {
  violent: 'جرائم العنف',
  financial: 'الجرائم المالية',
  cyber: 'الجرائم الإلكترونية',
  trafficking: 'جرائم الاتجار بالبشر',
  terrorism: 'الإرهاب',
  ai_enabled: 'الجرائم المدعومة بالذكاء الاصطناعي',
  children: 'الجرائم ضد الأطفال',
  drugs: 'جرائم المخدرات',
  organized_crime: 'الجريمة المنظمة',
  other: 'أخرى'
};

const sourceTypeAr = {
  academic: 'أكاديمية',
  governmental: 'حكومية',
  international_org: 'منظمات دولية',
  news: 'إخبارية'
};

const regionAr = {
  UAE: 'الإمارات',
  GCC: 'دول الخليج',
  Middle_East: 'الشرق الأوسط',
  Europe: 'أوروبا',
  Americas: 'الأمريكتان',
  Africa: 'أفريقيا',
  Asia: 'آسيا',
  Oceania: 'أوقيانوسيا',
  Global: 'عالمي'
};

const reportTypeAr = {
  daily: 'يومي',
  weekly: 'أسبوعي',
  monthly: 'شهري',
  quarterly: 'ربع سنوي',
  semiannual: 'نصف سنوي',
  annual: 'سنوي'
};

const monthAr = {
  '01': 'يناير', '02': 'فبراير', '03': 'مارس', '04': 'أبريل',
  '05': 'مايو', '06': 'يونيو', '07': 'يوليو', '08': 'أغسطس',
  '09': 'سبتمبر', '10': 'أكتوبر', '11': 'نوفمبر', '12': 'ديسمبر'
};

// ─── Helpers ───
function escapeHtml(text) {
  if (text === null || text === undefined) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function num(v) {
  const n = Number(v);
  return isNaN(n) ? 0 : n;
}

function fmtDate(d) {
  if (!d) return '—';
  try {
    return new Date(d).toLocaleDateString('ar-AE', {
      timeZone: 'Asia/Dubai', year: 'numeric', month: 'long', day: 'numeric'
    });
  } catch (e) {
    return String(d);
  }
}

function fmtDateTime(d) {
  if (!d) return '—';
  try {
    return new Date(d).toLocaleString('ar-AE', {
      timeZone: 'Asia/Dubai', year: 'numeric', month: 'short', day: 'numeric',
      hour: '2-digit', minute: '2-digit'
    });
  } catch (e) {
    return String(d);
  }
}

// Horizontal bar list from a {key: count} object
function barList(dataObj, labelMap) {
  const entries = Object.entries(dataObj || {})
    .map(([k, v]) => [k, num(v)])
    .sort((a, b) => b[1] - a[1]);
  if (entries.length === 0) {
    return '<div class="empty">لا توجد بيانات بعد</div>';
  }
  const max = Math.max(...entries.map(e => e[1]), 1);
  return entries.map(([key, count]) => {
    const label = (labelMap && labelMap[key]) || key;
    const pct = Math.max(Math.round((count / max) * 100), 3);
    return '<div class="bar-row">' +
      '<span class="bar-label">' + escapeHtml(label) + '</span>' +
      '<span class="bar-track"><span class="bar-fill" style="width:' + pct + '%"></span></span>' +
      '<span class="bar-value">' + count + '</span>' +
      '</div>';
  }).join('');
}

// ─── Statistics ───
const totalReferences = num(statsRow.total_references);
const recentAdditions = num(statsRow.recent_additions);
const bySourceType = statsRow.by_source_type || {};
const byCrimeType = statsRow.by_crime_type || {};
const byRegion = statsRow.by_region || {};
const byYear = statsRow.by_year || {};
const mostAccessed = Array.isArray(statsRow.most_accessed) ? statsRow.most_accessed : [];

const totalReports = typeSummary.reduce((sum, r) => sum + num(r.total), 0);
const totalEmailsSent = typeSummary.reduce((sum, r) => sum + num(r.emails_sent), 0);

// ─── Monthly timeline column chart ───
let timelineHtml;
if (timeline.length === 0) {
  timelineHtml = '<div class="empty">لا توجد بيانات بعد</div>';
} else {
  const maxCnt = Math.max(...timeline.map(t => num(t.cnt)), 1);
  timelineHtml = '<div class="columns">' + timeline.map(t => {
    const cnt = num(t.cnt);
    const h = Math.max(Math.round((cnt / maxCnt) * 100), 4);
    const parts = String(t.month).split('-');
    const label = (monthAr[parts[1]] || parts[1] || '') + ' ' + (parts[0] || '');
    return '<div class="column">' +
      '<span class="column-value">' + cnt + '</span>' +
      '<span class="column-bar" style="height:' + h + '%"></span>' +
      '<span class="column-label">' + escapeHtml(label) + '</span>' +
      '</div>';
  }).join('') + '</div>';
}

// ─── Report type summary table ───
const typeSummaryRows = typeSummary.length === 0
  ? '<tr><td colspan="4" class="empty">لم يتم إنشاء أي تقارير بعد</td></tr>'
  : Object.keys(reportTypeAr).map(type => {
      const row = typeSummary.find(r => r.report_type === type);
      if (!row) return '';
      return '<tr>' +
        '<td><span class="badge badge-' + type + '">' + reportTypeAr[type] + '</span></td>' +
        '<td>' + num(row.total) + '</td>' +
        '<td>' + num(row.emails_sent) + '</td>' +
        '<td>' + fmtDateTime(row.last_run) + '</td>' +
        '</tr>';
    }).join('');

// ─── Recent reports table ───
const recentReportRows = recentReports.length === 0
  ? '<tr><td colspan="6" class="empty">لم يتم إنشاء أي تقارير بعد</td></tr>'
  : recentReports.map(r => {
      const title = r.report_title_ar || r.report_title || '—';
      const emailStatus = r.email_sent
        ? '<span class="status status-ok">✓ تم الإرسال</span>'
        : '<span class="status status-pending">لم يُرسل</span>';
      return '<tr>' +
        '<td><span class="badge badge-' + escapeHtml(r.report_type) + '">' + (reportTypeAr[r.report_type] || escapeHtml(r.report_type)) + '</span></td>' +
        '<td class="cell-title">' + escapeHtml(title) + '</td>' +
        '<td>' + fmtDate(r.report_date) + '</td>' +
        '<td>' + num(r.references_count) + '</td>' +
        '<td>' + num(r.word_count) + '</td>' +
        '<td>' + emailStatus + '</td>' +
        '</tr>';
    }).join('');

// ─── Recent references table ───
const recentRefRows = recentRefs.length === 0
  ? '<tr><td colspan="5" class="empty">لا توجد مراجع بعد</td></tr>'
  : recentRefs.map(r => {
      const title = r.title_ar || r.title || '—';
      const titleCell = r.url
        ? '<a href="' + escapeHtml(r.url) + '" target="_blank" rel="noopener">' + escapeHtml(title) + '</a>'
        : escapeHtml(title);
      const crimes = Array.isArray(r.crime_type)
        ? r.crime_type.map(c => crimeTypeAr[c] || c).join('، ')
        : '—';
      const regions = Array.isArray(r.region)
        ? r.region.map(g => regionAr[g] || g).join('، ')
        : '—';
      return '<tr>' +
        '<td class="cell-title">' + titleCell + '</td>' +
        '<td>' + (sourceTypeAr[r.source_type] || escapeHtml(r.source_type)) + '</td>' +
        '<td>' + escapeHtml(crimes) + '</td>' +
        '<td>' + escapeHtml(regions) + '</td>' +
        '<td>' + fmtDate(r.date_added) + '</td>' +
        '</tr>';
    }).join('');

// ─── Most accessed references list ───
const mostAccessedHtml = mostAccessed.length === 0
  ? '<div class="empty">لا توجد بيانات بعد</div>'
  : '<ol class="accessed-list">' + mostAccessed.slice(0, 5).map(r =>
      '<li><span class="accessed-title">' + escapeHtml(r.title) + '</span>' +
      '<span class="accessed-count">' + num(r.access_count) + ' مرة</span></li>'
    ).join('') + '</ol>';

const generatedAt = new Date().toLocaleString('ar-AE', {
  timeZone: 'Asia/Dubai', dateStyle: 'full', timeStyle: 'short'
});

// ─── Assemble page ───
const html = '<!DOCTYPE html>' +
'<html lang="ar" dir="rtl">' +
'<head>' +
'<meta charset="UTF-8">' +
'<meta name="viewport" content="width=device-width, initial-scale=1.0">' +
'<title>لوحة معلومات الرصد الجنائي</title>' +
'<style>' +
'*{margin:0;padding:0;box-sizing:border-box}' +
'body{font-family:"Segoe UI",Tahoma,"Noto Kufi Arabic",Arial,sans-serif;background:#eef1f7;color:#1c2333;line-height:1.6}' +
'.header{background:linear-gradient(135deg,#14213d 0%,#1f3a63 100%);color:#fff;padding:32px 24px;text-align:center}' +
'.header h1{font-size:26px;margin-bottom:4px}' +
'.header .subtitle{font-size:14px;color:#c9d4e8;letter-spacing:1px}' +
'.header .timestamp{margin-top:10px;font-size:13px;color:#9db2d4}' +
'.container{max-width:1200px;margin:0 auto;padding:24px 16px}' +
'.stat-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin-bottom:24px}' +
'.stat-card{background:#fff;border-radius:12px;padding:20px;box-shadow:0 1px 4px rgba(20,33,61,.08);border-top:4px solid #1f3a63}' +
'.stat-card .stat-value{font-size:34px;font-weight:700;color:#14213d}' +
'.stat-card .stat-label{font-size:14px;color:#5a6a85;margin-top:4px}' +
'.stat-card.accent-green{border-top-color:#0e7a4d}' +
'.stat-card.accent-gold{border-top-color:#b8860b}' +
'.stat-card.accent-teal{border-top-color:#0d7387}' +
'.grid-2{display:grid;grid-template-columns:repeat(auto-fit,minmax(440px,1fr));gap:16px;margin-bottom:24px}' +
'.panel{background:#fff;border-radius:12px;padding:20px;box-shadow:0 1px 4px rgba(20,33,61,.08)}' +
'.panel h2{font-size:17px;color:#14213d;margin-bottom:14px;padding-bottom:10px;border-bottom:2px solid #eef1f7}' +
'.panel h2 .en{font-size:11px;color:#8b99b3;font-weight:400;margin-inline-start:8px}' +
'.bar-row{display:flex;align-items:center;gap:10px;margin-bottom:9px}' +
'.bar-label{flex:0 0 165px;font-size:13px;color:#33415c}' +
'.bar-track{flex:1;background:#eef1f7;border-radius:6px;height:16px;overflow:hidden}' +
'.bar-fill{display:block;height:100%;background:linear-gradient(270deg,#1f3a63,#3f6bb0);border-radius:6px}' +
'.bar-value{flex:0 0 36px;font-size:13px;font-weight:700;color:#14213d;text-align:center}' +
'.columns{display:flex;align-items:flex-end;gap:8px;height:180px;padding-top:10px}' +
'.column{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%}' +
'.column-value{font-size:11px;font-weight:700;color:#33415c;margin-bottom:3px}' +
'.column-bar{display:block;width:70%;max-width:42px;background:linear-gradient(180deg,#3f6bb0,#1f3a63);border-radius:5px 5px 0 0;min-height:4px}' +
'.column-label{font-size:10px;color:#8b99b3;margin-top:6px;white-space:nowrap}' +
'table{width:100%;border-collapse:collapse;font-size:13px}' +
'th{background:#f4f6fb;color:#33415c;text-align:right;padding:9px 10px;font-size:12px;border-bottom:2px solid #e3e8f2}' +
'td{padding:9px 10px;border-bottom:1px solid #eef1f7;color:#33415c;vertical-align:top}' +
'tr:hover td{background:#f9fafd}' +
'.cell-title{max-width:380px}' +
'.cell-title a{color:#1f5fbf;text-decoration:none}' +
'.cell-title a:hover{text-decoration:underline}' +
'.badge{display:inline-block;padding:2px 10px;border-radius:20px;font-size:12px;font-weight:600;background:#e7edf7;color:#1f3a63}' +
'.badge-daily{background:#e3f0ff;color:#1f5fbf}' +
'.badge-weekly{background:#e6f6ee;color:#0e7a4d}' +
'.badge-monthly{background:#fdf3e0;color:#a06a00}' +
'.badge-quarterly{background:#f3e8fd;color:#7233b8}' +
'.badge-semiannual{background:#e0f5f8;color:#0d7387}' +
'.badge-annual{background:#fde8e8;color:#b43333}' +
'.status{font-size:12px;font-weight:600}' +
'.status-ok{color:#0e7a4d}' +
'.status-pending{color:#a06a00}' +
'.accessed-list{padding-inline-start:20px}' +
'.accessed-list li{margin-bottom:8px;font-size:13px;display:flex;justify-content:space-between;gap:10px}' +
'.accessed-title{color:#33415c}' +
'.accessed-count{color:#1f3a63;font-weight:700;white-space:nowrap}' +
'.empty{text-align:center;color:#8b99b3;padding:24px;font-size:14px}' +
'.table-wrap{overflow-x:auto}' +
'.footer{text-align:center;padding:20px;color:#8b99b3;font-size:12px}' +
'@media(max-width:640px){.bar-label{flex-basis:110px}.column-label{transform:rotate(-45deg);margin-top:12px}}' +
'</style>' +
'</head>' +
'<body>' +
'<div class="header">' +
'<h1>لوحة معلومات الرصد الجنائي</h1>' +
'<div class="subtitle">CRIMINAL INTELLIGENCE DASHBOARD</div>' +
'<div class="timestamp">آخر تحديث: ' + generatedAt + ' (بتوقيت الإمارات)</div>' +
'</div>' +
'<div class="container">' +

// Stat cards
'<div class="stat-cards">' +
'<div class="stat-card"><div class="stat-value">' + totalReferences + '</div><div class="stat-label">إجمالي المراجع في قاعدة البيانات</div></div>' +
'<div class="stat-card accent-green"><div class="stat-value">' + recentAdditions + '</div><div class="stat-label">مراجع أُضيفت خلال آخر 30 يومًا</div></div>' +
'<div class="stat-card accent-gold"><div class="stat-value">' + totalReports + '</div><div class="stat-label">إجمالي التقارير المُنشأة</div></div>' +
'<div class="stat-card accent-teal"><div class="stat-value">' + totalEmailsSent + '</div><div class="stat-label">تقارير أُرسلت بالبريد الإلكتروني</div></div>' +
'</div>' +

// Distribution charts
'<div class="grid-2">' +
'<div class="panel"><h2>المراجع حسب نوع الجريمة<span class="en">BY CRIME TYPE</span></h2>' + barList(byCrimeType, crimeTypeAr) + '</div>' +
'<div class="panel"><h2>المراجع حسب المنطقة الجغرافية<span class="en">BY REGION</span></h2>' + barList(byRegion, regionAr) + '</div>' +
'<div class="panel"><h2>المراجع حسب نوع المصدر<span class="en">BY SOURCE TYPE</span></h2>' + barList(bySourceType, sourceTypeAr) + '</div>' +
'<div class="panel"><h2>المراجع حسب سنة النشر<span class="en">BY PUBLICATION YEAR</span></h2>' + barList(byYear, null) + '</div>' +
'</div>' +

// Monthly timeline
'<div class="panel" style="margin-bottom:24px"><h2>المراجع المُضافة شهريًا — آخر 12 شهرًا<span class="en">MONTHLY ADDITIONS</span></h2>' + timelineHtml + '</div>' +

// Report activity
'<div class="grid-2">' +
'<div class="panel"><h2>نشاط التقارير حسب النوع<span class="en">REPORT ACTIVITY</span></h2>' +
'<div class="table-wrap"><table><thead><tr><th>النوع</th><th>العدد</th><th>أُرسل بالبريد</th><th>آخر تشغيل</th></tr></thead><tbody>' + typeSummaryRows + '</tbody></table></div></div>' +
'<div class="panel"><h2>المراجع الأكثر استخدامًا<span class="en">MOST ACCESSED</span></h2>' + mostAccessedHtml + '</div>' +
'</div>' +

// Recent reports
'<div class="panel" style="margin-top:24px"><h2>أحدث التقارير<span class="en">RECENT REPORTS</span></h2>' +
'<div class="table-wrap"><table><thead><tr><th>النوع</th><th>عنوان التقرير</th><th>تاريخ التقرير</th><th>المراجع</th><th>الكلمات</th><th>حالة الإرسال</th></tr></thead><tbody>' + recentReportRows + '</tbody></table></div></div>' +

// Recent references
'<div class="panel" style="margin-top:24px"><h2>أحدث المراجع المُضافة<span class="en">RECENT REFERENCES</span></h2>' +
'<div class="table-wrap"><table><thead><tr><th>العنوان</th><th>نوع المصدر</th><th>نوع الجريمة</th><th>المنطقة</th><th>تاريخ الإضافة</th></tr></thead><tbody>' + recentRefRows + '</tbody></table></div></div>' +

'</div>' +
'<div class="footer">نظام الرصد الجنائي الآلي — n8n Automated Criminal Intelligence Reports</div>' +
'</body></html>';

return { json: { html } };
